    "coverLabel": "Astuce #003",
    "coverAlt": "Gestionnaire des tâches Windows, onglet Performance Mémoire",
    "seoTitle": "Voir quelle application consomme la RAM (Gestionnaire des tâches)",
    "seoDescription": "Utilisez Ctrl + Shift + Échap puis Performance > Mémoire pour identifier les processus gourmands en RAM.",
    "ogTitle": "Optimiser la RAM : lire le Gestionnaire des tâches",
    "ogDescription": "Repérez rapidement les processus qui saturent la mémoire sous Windows.",
    "primaryKeyword": "consommation RAM Windows",
